reference.setup:
{
    alpha <- 0.05
    groups_of <- function(...) lapply(list(...), function(x) x[!is.na(x)])
    raw <- function(m, s, n) if (n == 1) 
        m
    else as.numeric(scale(seq_len(n))) * s + m
    gauss <- local({
        i <- 1:11
        b <- i/sqrt(4 * i^2 - 1)
        e <- eigen(diag(0, 12) + `[<-`(matrix(0, 12, 12), cbind(c(i, i + 1), c(i + 
            1, i)), c(b, b)), symmetric = TRUE)
        list(x = e$values, w = 2 * e$vectors[1, ]^2)
    })
    on_pieces <- function(br) {
        a <- head(br, -1)
        h <- diff(br)/2
        list(x = as.vector(outer(gauss$x, h) + rep(a + h, each = 12)), w = as.vector(outer(gauss$w, 
            h)))
    }
    x_nodes <- function(c, df) {
        top <- qchisq(1e-16, df, lower.tail = FALSE)
        k <- df * (seq(0.5, 3 * sqrt(df) + 10, by = 0.5)/c)^2
        on_pieces(sort(unique(c(0, qchisq(c(1e-13, 1e-10, 1e-07, 1e-04, 0.01, 0.2, 
            0.5, 0.8, 0.99, 1 - 1e-07), df), k[k < top], top))))
    }
    dunnett <- function(c, lam, df) {
        sig <- sqrt(1 - lam^2)
        xn <- x_nodes(c, df)
        zt <- on_pieces(seq(-1, 1, length.out = 61))
        given_x <- vapply(xn$x, function(x) {
            s <- sqrt(x/df)
            reach <- (c * s + 9)/min(lam) + 2
            z <- reach * zt$x
            q <- pmin(pnorm(outer(z, lam, function(z, l) (-c * s - l * z))/rep(sig, 
                each = length(z))) + pnorm(outer(z, lam, function(z, l) (c * s - 
                l * z))/rep(sig, each = length(z)), lower.tail = FALSE), 1)
            reach * sum(zt$w * dnorm(z) * (1 - exp(rowSums(log1p(-q))))) + 2 * pnorm(-reach)
        }, 0)
        min(1, sum(xn$w * dchisq(xn$x, df) * given_x))
    }
    smm <- function(c, k, df) {
        xn <- x_nodes(c, df)
        min(1, sum(xn$w * dchisq(xn$x, df) * (1 - exp(k * log1p(-2 * pnorm(c * sqrt(xn$x/df), 
            lower.tail = FALSE))))))
    }
    critical <- function(p) uniroot(function(c) p(c) - alpha, c(0.5, 50), tol = 1e-13)$root
    oneway <- function(groups, welch = FALSE, comps = "all", control = 1, test = "tukey", 
        from = "values") {
        k <- length(groups)
        n <- vapply(groups, length, 0)
        m <- vapply(groups, mean, 0)
        v <- vapply(groups, function(x) if (length(x) > 1) 
            var(x)
        else 0, 0)
        y <- unlist(groups)
        g <- factor(rep(seq_len(k), n))
        fit <- aov(y ~ g)
        tab <- summary(fit)[[1]]
        out <- list(k = k, n_total = sum(n), ss_between = tab[1, "Sum Sq"], ss_within = tab[2, 
            "Sum Sq"], ss_total = sum(tab[, "Sum Sq"]), df_between = tab[1, "Df"], 
            df_within = tab[2, "Df"], df_total = sum(n) - 1, ms_between = tab[1, 
                "Mean Sq"], ms_within = tab[2, "Mean Sq"], f = tab[1, "F value"], 
            p = tab[1, "Pr(>F)"], r_squared = tab[1, "Sum Sq"]/sum(tab[, "Sum Sq"]))
        out$bartlett <- if (all(n >= 5) && all(v > 0)) {
            b <- bartlett.test(groups)
            list(statistic = unname(b$statistic), df = unname(b$parameter), p = b$p.value)
        }
        else {
            NA
        }
        if (welch) {
            w <- oneway.test(y ~ g, var.equal = FALSE)
            out$welch <- list(statistic = unname(w$statistic), dfn = unname(w$parameter[1]), 
                dfd = unname(w$parameter[2]), p = w$p.value)
            N <- sum(n)
            den <- (1 - n/N) * v
            fstar <- tab[1, "Sum Sq"]/sum(den)
            dfd <- sum(den)^2/sum(den^2/(n - 1))
            out$brown_forsythe <- list(statistic = fstar, dfn = k - 1, dfd = dfd, 
                p = pf(fstar, k - 1, dfd, lower.tail = FALSE))
        }
        out$groups <- lapply(seq_len(k), function(i) {
            r <- list(n = n[i], mean = m[i], sd = if (n[i] > 1) sd(groups[[i]]) else NA)
            if (from == "values") 
                r$median <- median(groups[[i]])
            r
        })
        out$comparisons <- if (comps == "none") 
            list()
        else comparisons(groups, fit, welch, comps, control, test)
        out$brown_forsythe_sd <- if (from == "values") {
            dev <- abs(y - ave(y, g, FUN = median))
            if (sum((dev - ave(dev, g))^2) > 0) {
                bt <- summary(aov(dev ~ g))[[1]]
                list(statistic = bt[1, "F value"], dfn = bt[1, "Df"], dfd = bt[2, 
                  "Df"], p = bt[1, "Pr(>F)"])
            }
            else NA
        }
        else {
            NA
        }
        out
    }
    comparisons <- function(groups, fit, welch, comps, control, test) {
        k <- length(groups)
        n <- vapply(groups, length, 0)
        m <- vapply(groups, mean, 0)
        v <- vapply(groups, function(x) if (length(x) > 1) 
            var(x)
        else 0, 0)
        mse <- sum(residuals(fit)^2)/fit$df.residual
        df <- fit$df.residual
        pairs <- unname(if (comps == "all") {
            do.call(rbind, lapply(seq_len(k - 1), function(i) cbind(i, (i + 1):k)))
        }
        else {
            cbind(control, seq_len(k)[-control])
        })
        K <- nrow(pairs)
        hsd <- if (test == "tukey") 
            TukeyHSD(fit, conf.level = 1 - alpha)$g
        else NULL
        if (test == "dunnett") {
            others <- pairs[, 2]
            lam <- sqrt(n[others]/(n[others] + n[control]))
            dunnett_crit <- critical(function(c) dunnett(c, lam, df))
        }
        lapply(seq_len(K), function(x) {
            i <- pairs[x, 1]
            j <- pairs[x, 2]
            d <- m[i] - m[j]
            if (welch) {
                se <- sqrt(v[i]/n[i] + v[j]/n[j])
                nu <- se^4/((v[i]/n[i])^2/(n[i] - 1) + (v[j]/n[j])^2/(n[j] - 1))
            }
            else {
                se <- sqrt(mse * (1/n[i] + 1/n[j]))
                nu <- df
            }
            t <- abs(d)/se
            r <- switch(test, tukey = {
                h <- hsd[paste0(j, "-", i), ]
                list(stat = sqrt(2) * t, lower = -h[["upr"]], upper = -h[["lwr"]], 
                  p = h[["p adj"]])
            }, `games-howell` = {
                half <- qtukey(1 - alpha, k, nu)/sqrt(2) * se
                list(stat = sqrt(2) * t, lower = d - half, upper = d + half, p = ptukey(sqrt(2) * 
                  t, k, nu, lower.tail = FALSE))
            }, bonferroni = {
                half <- qt(1 - alpha/(2 * K), nu) * se
                list(stat = t, lower = d - half, upper = d + half, p = min(1, K * 
                  2 * pt(t, nu, lower.tail = FALSE)))
            }, sidak = , `tamhane-t2` = {
                a1 <- 1 - (1 - alpha)^(1/K)
                half <- qt(1 - a1/2, nu) * se
                p1 <- 2 * pt(t, nu, lower.tail = FALSE)
                list(stat = t, lower = d - half, upper = d + half, p = 1 - exp(K * 
                  log1p(-p1)))
            }, dunnett = {
                half <- dunnett_crit * se
                list(stat = t, lower = d - half, upper = d + half, p = dunnett(t, 
                  lam, df))
            }, `dunnett-t3` = {
                half <- critical(function(c) smm(c, K, nu)) * se
                list(stat = t, lower = d - half, upper = d + half, p = smm(t, K, 
                  nu))
            })
            list(i = i, j = j, diff = d, se = se, df = nu, statistic = r$stat, ci_lower = r$lower, 
                ci_upper = r$upper, p = r$p)
        })
    }
    summary_case <- function(means, sds, ns, ...) {
        groups <- lapply(seq_along(means), function(i) raw(means[i], sds[i], ns[i]))
        oneway(groups, ..., from = "summary")
    }
}

